// Поле escrow отвечает на один вопрос: можно ли в этой сети СЕТТЛИТЬСЯ.
//
// Своп заканчивается там, где лежит контракт, поэтому сеть без контракта показываем в списке, но
// выбрать не даём (в интерфейсе она серая с пометкой "coming soon"). Пока контракт не задеплоен
// нигде, демка работает в режиме имитации: mode "simulated" - фондирование эскроу подделывается
// (simulateEscrowFunding), реальных денег никто не двигает, и это честно написано в UI.
//
//   escrow: { address: null, mode: "simulated" }  - демо-режим, выбрать можно
//   escrow: { address: "0x…", mode: "live" }       - контракт задеплоен (сеть закрепляется за ним)
//   escrow: null                                   - контракта нет и не планировался: "coming soon"
//
// СЕТИ, ГДЕ DEX-НОГА ВКЛЮЧЕНА И ИЗМЕРЯЕТСЯ (список DEX_CHAINS ниже). Он именно в ДАННЫХ, и это не
// украшение: обходить весь реестр нельзя, потому что большинство сетей в статусе coming soon - по ним
// работа не ведётся, пулы не ищутся и адреса не подтверждаются. Когда придёт время следующей сети, она
// добавляется ОДНОЙ СТРОКОЙ в DEX_CHAINS и блоком uniswap у себя - и попадает и в интерфейс, и в замер
// (tools/check-uniswap-quote.mjs берёт список сетей отсюда, а не обходом CHAINS).
//
// ПОЧЕМУ ИМЕННО ЭТИ: arbitrum-sepolia (421614) - демо-сеть, где развёрнут наш эскроу и идут все прогоны;
// arbitrum (42161) и mainnet (1) - боевые сети, где видно, что маршрут живой на настоящей ликвидности.
export const DEX_CHAINS = ["arbitrum-sepolia", "arbitrum", "mainnet"];

