export const DEFAULT_CHAIN = "arbitrum-sepolia";

// СПИСОК ДОПУЩЕННЫХ ПРОВАЙДЕРОВ - ПОЛИТИКА ИНТЕРФЕЙСА, А НЕ ПРОВЕРКА ЦЕПИ (#76/#77).
//
// Цепь отвечает на ДРУГОЙ вопрос: чей ключ подписал котировку (реестр мейкеров, providerOf - его читает
// ядро, sdk/src/quotes.mjs). ЭТОТ список - решение интерфейса о том, с кем он вообще торгует. Провайдер,
// чей адрес подтверждён цепью, но не назван здесь, не проходит (код `quote-provider-not-allowed`), и это
// видно ЧЕЛОВЕКУ до подписи: комиссию показывает котировка, а её выдача не состоится.
//
// ПОЧЕМУ ОТДЕЛЬНЫМ СПИСКОМ, А НЕ ЧТЕНИЕМ ИЗ БЕКЕНДА. Отбор - дело интерфейса: он меняется здесь, без
// передеплоя контрактов и без правок у чужого узла. Такой же список есть и у бекенда
// (`ARRAKIS_ALLOWED_PROVIDERS`, app/app.env) - это ДВЕ независимые ступени одного решения, а не копия:
// страница защищает себя сама, даже если сервис настроен иначе.
//
// АДРЕСА - в нижнем регистре, как их отдаёт котировка (поле `provider`). Сеть без записи здесь означает
// "список не задан" (политика не применяется), а НЕ "никого не пускать": иначе сеть без настройки встала бы
// целиком. Заполнять список для сети нужно тогда, когда там зарегистрирован мейкер.
export const ALLOWED_PROVIDERS = {
  "local-anvil": ["0x60af2ad4963c738aa6ac16d6cb0af1982508ba21"],
};

// Список допущенных для сети - или null, если он не задан (политики нет). Ядро принимает и массив, и
// предикат; здесь отдаётся массив в нижнем регистре: список - это то, что видно и меняется в одном месте.
export function allowedProvidersFor(chainOrId) {
  const id = typeof chainOrId === "string" ? chainOrId : chainOrId && chainOrId.id;
  const list = ALLOWED_PROVIDERS[id];
  if (!Array.isArray(list) || list.length === 0) return null;
  return list.map((a) => String(a).toLowerCase());
}

// СПИСОК ИЗВЕСТНЫХ СБОРОК ФАБРИКИ - ПОЛИТИКА ИНТЕРФЕЙСА, РЯДОМ С allowedProviders (#103).
// Значение - extcodehash (keccak256 кода) фабрики, которую интерфейс готов принять: фабрика приходит из
// ЗАПИСИ РЕЕСТРА провайдера, а её код сверяется с этим списком. Пусто для сети = политики нет (фабрика всё
// равно обязана быть названа записью и совпасть с подписанной котировкой). Заполняется при развёртывании:
// у фабрики нет immutable-полей, поэтому одна и та же сборка даёт один и тот же хеш у любого, кто её
// развернул, - своей фабрикой провайдер попадает в тот же список.
export const KNOWN_FACTORY_CODES = {};

export function knownFactoryCodesFor(chainOrId) {
  const id = typeof chainOrId === "string" ? chainOrId : chainOrId && chainOrId.id;
  const list = KNOWN_FACTORY_CODES[id];
  if (!Array.isArray(list) || list.length === 0) return null;
  return list.map((h) => String(h).toLowerCase());
}

// СПИСОК ИЗВЕСТНЫХ СБОРОК РЕАЛИЗАЦИИ ЭСКРОУ - ПОЛИТИКА ИНТЕРФЕЙСА (#114), при самой сети, где живёт адрес
// фабрики (escrow.address). Хеш её кода - КОНСТАНТА ПРОТОКОЛА (у реализации нет immutables), но политика
// может быть не задана: у сети без поля implementationCodeHash её НЕТ (старая фабрика пары не отдаёт).
// Пусто = политики нет; непусто = интерфейс торгует только через фабрики, ведущие на эту сборку.
export function knownImplementationCodesFor(chainOrId) {
  const id = typeof chainOrId === "string" ? chainOrId : chainOrId && chainOrId.id;
  const chain = CHAINS.find((c) => c.id === id) || chainById(id);
  const pinned = chain && chain.escrow ? chain.escrow.implementationCodeHash : null;
  if (typeof pinned !== "string" || !/^0x[0-9a-fA-F]{64}$/.test(pinned)) return null;
  return [pinned.toLowerCase()];
}

export function chainById(id) {
  return CHAINS.find((c) => c.id === id) || CHAINS.find((c) => c.id === DEFAULT_CHAIN) || CHAINS[0];
}

export function chainByChainId(chainId) {
  return CHAINS.find((c) => c.chainId === Number(chainId)) || null;
}

// Принимаемые токены сети: нативный первым, затем контрактные.
export function tokensOf(chainId) {
  const c = chainById(chainId);
  return [nativeOf(chainId), ...c.tokens];
}

export function nativeOf(chainId) {
  const c = chainById(chainId);
  return {
    symbol: c.native.symbol,
    label: c.native.symbol,
    address: null,
    decimals: c.native.decimals,
    usd: c.native.usd,
    cls: "ar-token-eth",
    native: true,
  };
}

// Токен по составному идентификатору "<chainId>:<SYMBOL>" либо по паре аргументов.
export function tokenById(idOrChainId, symbolMaybe) {
  let chainId = idOrChainId;
  let symbol = symbolMaybe;
  if (typeof idOrChainId === "string" && idOrChainId.includes(":")) {
    [chainId, symbol] = idOrChainId.split(":");
  }
  const list = tokensOf(chainId);
  return list.find((t) => t.symbol === String(symbol).toUpperCase()) || list[0];
}


