// называет себя на контуре CI. Она нужна, чтобы имя сети ПРИНИМАЛОСЬ: ядро сверяет xmrNetwork со списком
// сетей движка (sdk/src/config.mjs, STANDARD_XMR_NETWORKS), а адаптер кошелька ядра берёт список сетей
// из ЭТОГО реестра (sdk/src/adapters/monero-wallet.mjs). Кошелёк демки при этом остаётся stagenet.
export const XMR_NETWORKS = { app: "stagenet", mock: "stagenet", fakechain: "fakechain" };

// Страница sweep: отдельный домен со своей (более строгой) политикой и WASM-кошельком.
// Вывод XMR делает сам пользователь там, по своему recovery-файлу - демка за него не подписывает
// (см. .hermes/docs/09-sweep-origin.md).
// Куда ведёт ссылка на страницу вывода. В бою - боевой домен, на локальном стенде - его собственный адрес
// (там своя нода и свой бэкенд). Отдельная функция, чтобы правило было одним: ссылка и то, где страница
// действительно поднята, не должны расходиться.
export function sweepOrigin() {
  const h = typeof location !== "undefined" ? location.hostname : "";
  return /^(localhost|127\.0\.0\.1|\[::1\])$/.test(h) || /\.local$/.test(h) ? SWEEP.localOrigin : SWEEP.origin;
}

export const SWEEP = {
  origin: "https://sweep.arrakisswap.trade",
  localOrigin: "http://localhost:5195",
};

